use serde_json::{json, Value};
use sha2::{Digest,Sha256};
use std::{fs,path::Path};
const ROOT:&str="/home/ubuntu/src/zk-tools/zopro";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn sums(dir:&Path){fn list(p:&Path,out:&mut Vec<std::path::PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){list(&p,out)}else{out.push(p)}}}let mut paths=vec![];list(dir,&mut paths);paths.sort();let s=paths.iter().filter(|p|p.as_path()!=dir.join("SHA256SUMS")).map(|p|format!("{}  {}\n",hash(p),p.strip_prefix(dir).unwrap().display())).collect::<String>();fs::write(dir.join("SHA256SUMS"),s).unwrap();}
